<?php $this->assign('title', 'Personal de administración'); ?><div class="content admin-page"><div class="page-heading"><h1>Personal de administración</h1><a class="button" href="<?= $this->Url->build(['action'=>'add']) ?>">Nuevo registro</a></div><div class="table-responsive"><table><thead><tr><th>Persona</th><th>Cargo</th><th>Propiedad</th><th>Vigencia</th><th>Acciones</th></tr></thead><tbody><?php foreach($personal as $registro): ?><tr><td><?= h($registro->full_name) ?></td><td><?= h($registro->position) ?></td><td><?= h($registro->propiedades_horizontal->name) ?></td><td><?= $registro->active ? 'Activo' : 'Histórico' ?></td><td><a href="<?= $this->Url->build(['action'=>'edit',$registro->id]) ?>">Editar</a><?php if($registro->active): ?><?= $this->Form->postLink('Finalizar',['action'=>'finish',$registro->id],['confirm'=>'¿Finalizar la vinculación? El historial se conservará.']) ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
